#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BOOKS 100000

typedef struct {
    int book_id;
} Book;

typedef struct Node {
    int book_id;
    struct Node *next;
} Node;

typedef struct {
    Node *front;
    Node *rear;
    int size;
} Queue;

void initQueue(Queue *q) {
    q->front = q->rear = NULL;
    q->size = 0;
}

void enqueue(Queue *q, int book_id) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->book_id = book_id;
    newNode->next = NULL;
    if (q->rear == NULL) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    q->size++;
}

int dequeue(Queue *q) {
    if (q->front == NULL) return -1;
    Node *temp = q->front;
    int book_id = temp->book_id;
    q->front = q->front->next;
    if (q->front == NULL) q->rear = NULL;
    free(temp);
    q->size--;
    return book_id;
}

int isEmpty(Queue *q) {
    return q->front == NULL;
}

