int desk_books[MAX_BOOKS]; // 0 = not on desk, 1 = on desk

int main() {
    int dataset_num = 0;
    int n, q;

    while (scanf("%d %d", &n, &q) == 2) {
        if (n == 0 && q == 0) break;
        dataset_num++;

        // Initialize desk books array
        memset(desk_books, 0, sizeof(desk_books));

        // Read the initial books on desk
        int d;
        scanf("%d", &d);
        for (int i = 0; i < d; i++) {
            int book_id;
            scanf("%d", &book_id);
            desk_books[book_id] = 1;
        }

        // Read the requests queue
        Queue requests;
        initQueue(&requests);
        for (int i = 0; i < q; i++) {
            int book_id;
            scanf("%d", &book_id);
            enqueue(&requests, book_id);
        }

        long long total_cost = 0;

        // Process each request
        while (!isEmpty(&requests)) {
            int requested_book = dequeue(&requests);

            // Check if book is on desk
            if (desk_books[requested_book]) {
                total_cost += 1; // Cost to access desk
            } else {
                total_cost += 2; // Cost to access shelf (1) + desk (1)
                desk_books[requested_book] = 1; // Bring to desk
            }

            // Check for other same requests in the queue and remove them
            Queue temp;
            initQueue(&temp);
            while (!isEmpty(&requests)) {
                int bk = dequeue(&requests);
                if (bk != requested_book) {
                    enqueue(&temp, bk);
                } else {
                    // Another same request found, we can satisfy it from desk now
                    total_cost += 1; // Cost to access desk
                }
            }
            // Transfer back to requests
            while (!isEmpty(&temp)) {
                enqueue(&requests, dequeue(&temp));
            }
        }

        printf("Dataset %d: %lld\n", dataset_num, total_cost);
    }

    return 0;
}

