/*
This problem is the classic "Bookshelf / desk" simulation.

Model:
- There are n books initially on the shelf, ordered 1..n from left to right.
- m requests follow.
- To serve a request for book x:
  * If x is already on the desk:
      cost += number of books on desk above it + 1
      then move x to the top of the desk.
  * Otherwise:
      cost += number of books on desk + position of x on shelf
      remove x from shelf and place it on top of desk.

Efficient solution:
- Keep all books in one indexed sequence:
    [desk books ...][shelf books ...]
  where desk books occupy positions 1..topCount, with the top at position 1.
- Initially book i is at position m + i.
- When a book is requested, answer = number of books before its current position.
  Since positions 1..currentPos-1 correspond exactly to:
    all desk books above it (if on desk), or all desk books + shelf books before it.
  Then add 1 for the access cost.
- Move requested book to a new front position decreasing from m to 1.

Use Fenwick tree to maintain occupied positions.
*/

typedef long long ll;

typedef struct {
    int n;
    int *bit;
} Fenwick;

static void fenwick_init(Fenwick *fw, int n) {
    fw->n = n;
    fw->bit = (int *)calloc(n + 1, sizeof(int));
}

static void fenwick_add(Fenwick *fw, int idx, int val) {
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

static int fenwick_sum(Fenwick *fw, int idx) {
    int s = 0;
    while (idx > 0) {
        s += fw->bit[idx];
        idx -= idx & -idx;
    }
    return s;
}

static void fenwick_free(Fenwick *fw) {
    free(fw->bit);
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        int n, m;
        scanf("%d %d", &n, &m);

        int size = n + m + 2;
        Fenwick fw;
        fenwick_init(&fw, size);

        int *pos = (int *)malloc((n + 1) * sizeof(int));

        for (int i = 1; i <= n; ++i) {
            pos[i] = m + i;
            fenwick_add(&fw, pos[i], 1);
        }

        int front = m;
        ll ans = 0;

        for (int i = 0; i < m; ++i) {
            int x;
            scanf("%d", &x);

            ans += (ll)fenwick_sum(&fw, pos[x] - 1) + 1;

            fenwick_add(&fw, pos[x], -1);
            pos[x] = front;
            fenwick_add(&fw, pos[x], 1);
            front--;
        }

        printf("%lld\n", ans);

        free(pos);
        fenwick_free(&fw);
    }

    return 0;
}

