public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int N = sc.nextInt(); // number of books
            if (N == 0) break;
            int D = sc.nextInt(); // desk capacity
            int L = sc.nextInt(); // cost to get from shelf
            int Q = sc.nextInt(); // number of requests
            int[] requests = new int[Q];
            for (int i = 0; i < Q; i++) {
                requests[i] = sc.nextInt();
            }

            // OPT algorithm
            Set<Integer> desk = new HashSet<>();
            long totalCost = 0;

            for (int i = 0; i < Q; i++) {
                int book = requests[i];
                if (desk.contains(book)) {
                    totalCost += 1; // on desk
                } else {
                    totalCost += L; // on shelf, bring to desk
                    if (desk.size() < D) {
                        desk.add(book);
                    } else {
                        // evict book used furthest in future
                        int evict = -1;
                        int farthest = -1;
                        for (int b : desk) {
                            int nextUse = Integer.MAX_VALUE;
                            for (int j = i + 1; j < Q; j++) {
                                if (requests[j] == b) {
                                    nextUse = j;
                                    break;
                                }
                            }
                            if (nextUse > farthest) {
                                farthest = nextUse;
                                evict = b;
                            }
                        }
                        desk.remove(evict);
                        desk.add(book);
                    }
                }
            }

            System.out.println(totalCost);
        }
    }
}

