/*
 * Library / bookshelf simulation
 *
 * Interpretation used:
 * - There are n books, initially all on the shelf.
 * - A desk can hold at most k books.
 * - Processing a request for book x:
 *      * If x is already on the desk:
 *            cost += 1
 *      * Otherwise x is on the shelf:
 *            cost += 2
 *            If the desk is full, one book must be removed from the desk
 *            before placing x there.
 * - To minimize total cost, when eviction is needed we remove the desk book
 *   whose next use is farthest in the future (or never used again).
 *
 * Multiple datasets are read until EOF.
 * Expected input per dataset:
 *      n k m
 *      m integers: the sequence of requested books
 *
 * Output:
 *      total minimal cost for each dataset, one per line
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class BookInfo {
        int id;
        int nextPos;

        BookInfo(int id, int nextPos) {
            this.id = id;
            this.nextPos = nextPos;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer nObj = fs.nextInt();
            if (nObj == null) break;
            Integer kObj = fs.nextInt();
            Integer mObj = fs.nextInt();
            if (kObj == null || mObj == null) break;

            int n = nObj;
            int k = kObj;
            int m = mObj;

            int[] req = new int[m];
            for (int i = 0; i < m; i++) req[i] = fs.nextInt();

            long ans = solve(n, k, m, req);
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static long solve(int n, int k, int m, int[] req) {
        if (m == 0) return 0;

        // next occurrence for each request position
        int[] nextAt = new int[m];
        int INF = m + 5;
        int[] last = new int[n + 1];
        Arrays.fill(last, INF);

        for (int i = m - 1; i >= 0; i--) {
            int b = req[i];
            nextAt[i] = last[b];
            last[b] = i;
        }

        if (k == 0) {
            // No desk space: every request comes from shelf
            return 2L * m;
        }

        boolean[] onDesk = new boolean[n + 1];
        int[] currentNext = new int[n + 1];

        // Max-heap by next use; lazy deletion
        PriorityQueue<BookInfo> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.nextPos, a.nextPos));

        int deskSize = 0;
        long cost = 0;

        for (int i = 0; i < m; i++) {
            int b = req[i];
            int nxt = nextAt[i];

            if (onDesk[b]) {
                cost += 1;
                currentNext[b] = nxt;
                pq.add(new BookInfo(b, nxt));
            } else {
                cost += 2;

                if (deskSize == k) {
                    while (true) {
                        BookInfo top = pq.poll();
                        if (top != null && onDesk[top.id] && currentNext[top.id] == top.nextPos) {
                            onDesk[top.id] = false;
                            deskSize--;
                            break;
                        }
                    }
                }

                onDesk[b] = true;
                currentNext[b] = nxt;
                deskSize++;
                pq.add(new BookInfo(b, nxt));
            }
        }

        return cost;
    }
}

