int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, D, N;
    while (cin >> M >> D >> N) {
        if (M == 0 && D == 0 && N == 0) break;

        // Read book initial locations: 1 = desk, 0 = shelf
        vector<bool> onDesk(M + 1, false);
        for (int i = 1; i <= M; i++) {
            int loc;
            cin >> loc;
            onDesk[i] = (loc == 1);
        }

        // Read the requests
        vector<int> requests(N);
        for (int i = 0; i < N; i++) {
            cin >> requests[i];
        }

        // Desk capacity
        int deskCapacity = D;
        // Current number of books on desk
        int deskCount = 0;
        for (int i = 1; i <= M; i++) {
            if (onDesk[i]) deskCount++;
        }

        long long totalCost = 0;

        // Process each request
        for (int req : requests) {
            if (onDesk[req]) {
                // Book is already on desk: no cost, but we need to access it
                // According to problem, accessing a book on desk costs 0
                // but we still need to "use" it and it stays on desk
                continue;
            }

            // Book is on shelf, need to bring it to desk
            // Cost for accessing shelf = 1
            totalCost += 1;

            // If desk is full, we must remove one book to shelf
            if (deskCount >= deskCapacity) {
                // Find a book on desk that is not needed in the future,
                // or if all needed, remove any (FIFO-like: remove the one
                // that will be needed furthest in the future)
                // We'll scan from index 1 to M to find a candidate
                int removeBook = -1;
                int farthestUse = -1;

                for (int b = 1; b <= M; b++) {
                    if (!onDesk[b]) continue;
                    // Check when this book will be requested next
                    int nextUse = -1;
                    for (int j = 0; j < N; j++) {
                        if (requests[j] == b) {
                            nextUse = j;
                            break;
                        }
                    }
                    // If never used again, it's best to remove
                    if (nextUse == -1) {
                        removeBook = b;
                        break;
                    }
                    // Otherwise keep track of farthest future use
                    if (nextUse > farthestUse) {
                        farthestUse = nextUse;
                        removeBook = b;
                    }
                }

                // Remove that book to shelf
                onDesk[removeBook] = false;
                deskCount--;
                // Cost for moving to shelf = 1
                totalCost += 1;
            }

            // Now bring requested book to desk
            onDesk[req] = true;
            deskCount++;
            // Cost for moving to desk = 1
            totalCost += 1;
        }

        cout << totalCost << "\n";
    }

    return 0;
}

