/*
We model the classic "borrowers / desk / shelf" process.

Interpretation:
- There are m books, identified by names.
- A sequence of requests asks for copies of books.
- The librarian keeps at most k books on desks.
- Accessing a book already on a desk costs 1.
- If not on a desk, it must be taken from the shelf, costing 2.
- When desks are full and a new book must be placed on a desk, one desk book is returned to shelf.
  That return itself costs 1.
- We should minimize total cost.

Optimal eviction policy:
Evict the desk book whose next future use is farthest in the future
(or never used again). This is Belady's optimal cache policy.

Input format handled:
Multiple datasets until EOF.
For each dataset:
m k
m lines: book names
Then a sequence of request names terminated by the line "END"

This matches the standard style for this problem family.

For each dataset, output the total cost as an integer on its own line.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, k;
    while (cin >> m >> k) {
        string dummy;
        getline(cin, dummy); // consume endline

        unordered_map<string, int> id;
        id.reserve(m * 2 + 10);

        for (int i = 0; i < m; ++i) {
            string s;
            getline(cin, s);
            id[s] = i;
        }

        vector<int> req;
        while (true) {
            string s;
            if (!getline(cin, s)) break;
            if (s == "END") break;
            auto it = id.find(s);
            if (it != id.end()) req.push_back(it->second);
        }

        int n = (int)req.size();
        vector<int> nextPos(n, n + 1);
        vector<int> last(m, n + 1);

        for (int i = n - 1; i >= 0; --i) {
            nextPos[i] = last[req[i]];
            last[req[i]] = i;
        }

        vector<int> curNext(m, -1);
        vector<char> onDesk(m, 0);

        // set of (next_use_position, book_id) for books currently on desk
        set<pair<int,int>> desk;

        long long cost = 0;

        for (int i = 0; i < n; ++i) {
            int b = req[i];
            int nxt = nextPos[i];

            if (onDesk[b]) {
                cost += 1; // access from desk
                desk.erase({curNext[b], b});
                curNext[b] = nxt;
                desk.insert({curNext[b], b});
            } else {
                cost += 2; // get from shelf
                if ((int)desk.size() == k && k > 0) {
                    auto it = prev(desk.end()); // farthest next use
                    int evict = it->second;
                    desk.erase(it);
                    onDesk[evict] = 0;
                    curNext[evict] = -1;
                    cost += 1; // return evicted book to shelf
                }
                if (k > 0) {
                    onDesk[b] = 1;
                    curNext[b] = nxt;
                    desk.insert({curNext[b], b});
                }
            }
        }

        cout << cost << '\n';
    }

    return 0;
}
